/**
 * Saving words with nothing but the headword, for the moments the AI cannot
 * fill them: "Many at once" over the day's allowance, a refusal, an address
 * not yet confirmed. Saving a word never depends on the AI
 * (`marketing/research/2026-10-free-vs-pro.md`, section 4): the word is kept
 * now and filled later, with Improve on its own page.
 *
 * The words arrive the way Paste a text leaves them: no meanings at all,
 * the learner's own (`manual`), at the top of the notebook. A word the
 * notebook already has is left alone, and so is a repeat in the list.
 */
import { normalizeHeadword } from '@lexpad/core';
import { importWords, type ImportRow } from '@/db/mutations.js';
import { listWords } from '@/db/repo.js';
import { trackWords } from '@/features/celebrate/state.js';

/** Saves each headword plain, and answers how many were new to the notebook. */
export async function savePlainWords(
  notebookId: string,
  headwords: readonly string[],
  timeZone: string,
): Promise<number> {
  const known = new Set((await listWords(notebookId)).map((word) => normalizeHeadword(word.headword)));
  const rows: ImportRow[] = [];
  for (const raw of headwords) {
    const headword = raw.trim();
    const key = normalizeHeadword(headword);
    if (headword === '' || known.has(key)) continue;
    known.add(key);
    rows.push({
      ref: key,
      word: {
        headword,
        category: 'general',
        source: 'manual',
        meanings: [],
        expressions: [],
        collocations: [],
        relatedWords: [],
        relatedWordIds: [],
      },
      relatedRefs: [],
    });
  }
  if (rows.length === 0) return 0;
  return trackWords(() => importWords(notebookId, rows, timeZone));
}
