import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import type { LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Icon } from '@/components/ui/Icon.js';
import { ai as aiApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { aiPausedUntil, isRefusal, noteRefusal } from './quota.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { offerable, useBilling } from '@/features/billing/state.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { getActiveNotebook } from '@/db/repo.js';
import { addWord } from '@/db/mutations.js';
import { aiJobFromApi, type AiJobView } from '@/sync/mapping.js';
import { syncSoon } from '@/sync/store.js';
import { MAX_HINT_LENGTH } from './hints.js';
import { isRunning, watchJob } from './poll.js';
import { parseWordList } from './words.js';
import { savePlainWords } from './plain.js';
import styles from './AiCards.module.css';
import { trackWords } from '@/features/celebrate/state.js';

interface Context {
  notebookId: string | undefined;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
}

const EMPTY_CONTEXT: Context = { notebookId: undefined, targetLang: 'en', meaningLang: 'fa' };

async function loadContext(): Promise<Context> {
  const notebook = await getActiveNotebook();
  return {
    notebookId: notebook?.id,
    targetLang: notebook?.targetLang ?? 'en',
    meaningLang: notebook?.meaningLang ?? 'fa',
  };
}

/**
 * Generating cards with a model. Unlike every other screen this one needs the
 * network, because the work happens on the server; it says so plainly when
 * there is none, and nothing is written locally until the user accepts.
 */
export function AiCards(): React.JSX.Element {
  const navigate = useNavigate();
  const context = useLiveQuery(loadContext, EMPTY_CONTEXT, []);
  const [input, setInput] = useState('');
  const [hint, setHint] = useState('');
  const [job, setJob] = useState<AiJobView | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | undefined>(undefined);
  const [skipped, setSkipped] = useState<ReadonlySet<string>>(new Set());
  const [adding, setAdding] = useState(false);
  /**
   * Words the AI did not fill and that were saved plain instead: `some`
   * when the day had room for part of the list, `all` when it had none.
   * Saving never waits for the AI.
   */
  const [savedPlain, setSavedPlain] = useState<
    { part: 'some' | 'all' | 'unconfirmed'; count: number } | undefined
  >();
  const [savingPlain, setSavingPlain] = useState(false);
  const billing = useBilling((state) => state.state);
  const ensurePlan = useBilling((state) => state.ensure);
  useEffect(() => {
    ensurePlan();
  }, [ensurePlan]);
  // "…or with Pro" only where Pro can be offered: never to somebody who has
  // it, on a client that may not sell, or in a notebook Lexpad never charges for.
  const withPro = offerable(billing, context.targetLang, context.meaningLang);

  const words = parseWordList(input);
  const cards = job?.cards ?? [];
  // After a refusal the screen rests, quietly, until the allowance renews.
  const pausedUntil = useLiveQuery(() => aiPausedUntil(), undefined, []);
  const resting = pausedUntil !== undefined;
  const chosen = cards.filter((card) => !skipped.has(card.headword));
  const running = job !== undefined && isRunning(job);
  // The watch of the job in progress, stopped when a new one starts or the
  // screen closes.
  const watching = useRef<AbortController | undefined>(undefined);
  useEffect(
    () => () => {
      watching.current?.abort();
    },
    [],
  );

  /**
   * Watches a job while it runs. The server does the work, so there is
   * nothing to do here but look again, less often as it goes, until it
   * settles (`watchJob`).
   */
  const watch = (started: AiJobView): void => {
    watching.current?.abort();
    if (!isRunning(started)) return;
    const aborter = new AbortController();
    watching.current = aborter;
    watchJob(started, { signal: aborter.signal, onUpdate: setJob })
      .then((view) => {
        if (view.status === 'failed') setError(view.error ?? t('ai.failed'));
      })
      .catch((cause: unknown) => {
        if (aborter.signal.aborted) return;
        setError(isApiError(cause, 'offline') ? t('error.offline') : t('ai.failed'));
      });
  };

  /** Saves words plain and says so; a failure to save locally is said too. */
  const keepPlain = async (
    notebookId: string,
    list: readonly string[],
    part: 'some' | 'all' | 'unconfirmed',
  ): Promise<void> => {
    if (list.length === 0) return;
    try {
      await savePlainWords(notebookId, list, localTimeZone());
      void syncSoon();
      setSavedPlain({ part, count: list.length });
      // Every word is in the notebook now; asking again for the same list
      // tomorrow is what Improve on each word is for.
      if (part !== 'some') setInput('');
    } catch {
      setError(t('ai.plainFailed'));
    }
  };

  const generate = async (): Promise<void> => {
    const notebookId = context.notebookId;
    if (notebookId === undefined || words.length === 0) return;
    setBusy(true);
    setError(undefined);
    setSavedPlain(undefined);
    watching.current?.abort();
    setJob(undefined);
    setSkipped(new Set());
    try {
      // Partial: the day's room fills the first words, and the answer names
      // the rest, which are saved plain at once rather than refused.
      const view = aiJobFromApi(await aiApi.createCards(notebookId, words, hint.trim(), { partial: true }));
      setJob(view);
      if (view.status === 'failed') setError(view.error ?? t('ai.failed'));
      watch(view);
      await keepPlain(notebookId, view.plainWords, 'some');
    } catch (cause) {
      // Out of AI for today, or not until the address is confirmed: the
      // words are still the learner's, so they are saved before anything
      // else is said — and before the screen starts resting.
      if (isRefusal(cause) || (isApiError(cause) && cause.code === 'email_unverified')) {
        const refused = isRefusal(cause);
        await keepPlain(notebookId, words, refused ? 'all' : 'unconfirmed');
        await noteRefusal(cause);
        // The server says what to do about the address in its own words.
        if (!refused && isApiError(cause)) setError(cause.message);
        return;
      }
      await noteRefusal(cause);
      setError(isApiError(cause, 'offline') ? t('error.offline') : messageOf(cause));
    } finally {
      setBusy(false);
    }
  };

  /** While AI cards rest, the list can still be kept, plain. */
  const savePlainNow = async (): Promise<void> => {
    const notebookId = context.notebookId;
    if (notebookId === undefined || words.length === 0) return;
    setSavingPlain(true);
    setError(undefined);
    try {
      await keepPlain(notebookId, words, 'all');
    } finally {
      setSavingPlain(false);
    }
  };

  const addChosen = async (): Promise<void> => {
    const notebookId = context.notebookId;
    if (notebookId === undefined) return;
    setAdding(true);
    try {
      const timeZone = localTimeZone();
      await trackWords(async () => {
        for (const card of chosen) await addWord(notebookId, card, timeZone);
      });
      void syncSoon();
      void navigate('/notebook', { replace: true });
    } finally {
      setAdding(false);
    }
  };

  const toggle = (headword: string): void => {
    setSkipped((previous) => {
      const next = new Set(previous);
      if (next.has(headword)) next.delete(headword);
      else next.add(headword);
      return next;
    });
  };

  return (
    <main className={styles.screen}>
      <div className={styles.topBar}>
        <button
          type="button"
          className={styles.back}
          aria-label={t('action.back')}
          onClick={() => {
            void navigate(-1);
          }}
        >
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
        <h1 className={styles.title}>{t('ai.title')}</h1>
      </div>

      <p className={styles.lead}>{t('ai.lead')}</p>
      {resting && savedPlain === undefined && (
        <p className={styles.resting} role="status">
          {t('ai.resting')}
        </p>
      )}
      {/* What became of the words the AI could not fill: saved, every one,
          before any offer is made. */}
      {savedPlain !== undefined && (
        <p className={styles.resting} role="status">
          {savedPlain.part === 'unconfirmed'
            ? t('ai.allSavedPlain', { count: savedPlain.count })
            : savedPlain.part === 'some'
              ? withPro
                ? t('ai.restSavedPro')
                : t('ai.restSaved')
              : withPro
                ? t('ai.allSavedPro', { count: savedPlain.count })
                : t('ai.allSaved', { count: savedPlain.count })}
        </p>
      )}
      {/* The one moment somebody has been stopped by the very thing Pro
          lifts, so it is the one moment worth saying so — after their words
          are safe. When they are not stopped the same offer sits quietly at
          the foot of the screen instead of in the way of the work. */}
      {(resting || (savedPlain !== undefined && savedPlain.part !== 'unconfirmed')) && (
        <ProOffer occasion="resting" />
      )}

      <textarea
        className={styles.textarea}
        value={input}
        dir="auto"
        placeholder={t('ai.placeholder')}
        aria-label={t('ai.placeholder')}
        onChange={(event) => {
          setInput(event.target.value);
        }}
      />

      <input
        className={styles.hint}
        value={hint}
        dir="auto"
        maxLength={MAX_HINT_LENGTH}
        placeholder={t('ai.hintPlaceholder')}
        aria-label={t('ai.hintLabel')}
        onChange={(event) => {
          setHint(event.target.value);
        }}
      />

      <div className={styles.row}>
        <span className={styles.count}>{t('ai.count', { count: words.length })}</span>
        {resting ? (
          // Resting is no reason to lose a list: it can be kept as plain
          // words now and filled later.
          <button
            type="button"
            className={styles.generate}
            disabled={words.length === 0 || context.notebookId === undefined || savingPlain}
            onClick={() => {
              void savePlainNow();
            }}
          >
            {t('ai.savePlain', { count: words.length })}
          </button>
        ) : (
          <button
            type="button"
            className={styles.generate}
            disabled={words.length === 0 || context.notebookId === undefined || busy || running}
            onClick={() => {
              void generate();
            }}
          >
            {(busy || running) && <span className={styles.spinner} aria-hidden="true" />}
            {busy || running ? t('ai.working') : t('ai.generate')}
          </button>
        )}
      </div>

      {error !== undefined && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}

      {cards.length > 0 && (
        <>
          <div className={styles.preview}>
            {cards.map((card) => (
              <div key={card.headword} className={styles.card}>
                <div className={styles.cardTop}>
                  <input
                    type="checkbox"
                    className={styles.checkbox}
                    checked={!skipped.has(card.headword)}
                    aria-label={card.headword}
                    onChange={() => {
                      toggle(card.headword);
                    }}
                  />
                  <span className={styles.headword}>
                    <Bilingual lang={context.targetLang}>{card.headword}</Bilingual>
                  </span>
                  {card.level !== undefined && <span className={styles.tag}>{card.level}</span>}
                  {card.pos !== undefined && <span className={styles.tag}>{card.pos}</span>}
                </div>
                <p className={styles.meaning}>
                  <Bilingual lang={context.meaningLang}>{card.meaning}</Bilingual>
                </p>
                {card.gloss !== undefined && (
                  <p className={styles.gloss}>
                    <Bilingual lang={context.targetLang}>{card.gloss}</Bilingual>
                  </p>
                )}
                {card.example !== undefined && (
                  <p className={styles.example}>
                    <Bilingual lang={context.targetLang}>{card.example}</Bilingual>
                  </p>
                )}
                <p className={styles.extras}>
                  {t('add.extras', {
                    meanings: (card.extraMeanings ?? []).length + 1,
                    collocations: (card.collocations ?? []).length,
                    related: (card.relatedWords ?? []).length,
                  })}
                </p>
              </div>
            ))}
          </div>

          <span className={styles.spacer} />

          <button
            type="button"
            className={styles.add}
            disabled={adding || chosen.length === 0}
            onClick={() => {
              void addChosen();
            }}
          >
            {t('ai.addN', { count: chosen.length })}
          </button>
        </>
      )}

      {/* Out of the way, below the work, and only while nothing is in
          flight: somebody watching cards being written is busy, and an
          offer arriving then would read as a shove. */}
      {!resting && savedPlain === undefined && !busy && !running && cards.length === 0 && (
        <ProOffer occasion="aiIdle" subtle />
      )}
    </main>
  );
}

/** The server's own words when it explains a refusal, ours otherwise. */
function messageOf(cause: unknown): string {
  // A refusal is the allowance, not a fault; it gets the app's own words, no numbers.
  if (isRefusal(cause)) return t('ai.resting');
  return isApiError(cause) ? cause.message : t('ai.failed');
}
